{
  "interpretation": {
    "name": "PrepareSharedNutrunnerForLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Make the shared nutrunner NR7 ready and used at station st2 for the F30 fasteners of line 2, with the tightening evaluated and recorded. The requested calibration cannot be proposed because no calibration service exists.",
    "constraints": [
      "NR7 must be reserved exclusively before any use, and the reservation must be released at the end",
      "NR7 must be at st2 before configure-tool or tighten-fasteners is invoked",
      "The program (bolt count, torque, tolerance) must come only from get-program and never appear as a literal",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool must be delegated to agvexecutor",
      "Every tool-using step renews the lease with the reservation token and depends on reserve-tool",
      "Calibration is requested but no calibration service is available, so it is not part of this draft"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "One-off, for the next use of NR7 by line 2",
    "requested_capabilities": ["calibrate-tool"],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nr7-f30-tightening",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Tighten",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": ["move-to-station"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "move-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "Finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten",
            "service": "tighten-fasteners",
            "next": ["evaluate", "record"],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Finish",
        "next": null,
        "steps": [
          {
            "name": "move-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
